#!/usr/bin/env python3
"""
Test all models listed in a JSON config file by sending a simple prompt to an
OpenAI-compatible Chat Completions API.

Usage:
  python test_models.py path/to/config.json

Endpoint:
  http://127.0.0.1:4000/v1/chat/completions
"""

import argparse
import json
import os
import sys
import time
import urllib.request
import urllib.error


API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, dict) and isinstance(data.get("models"), list):
        items = data["models"]
    elif isinstance(data, list):
        items = data
    else:
        raise ValueError("Config JSON must be a list or a dict containing a 'models' list.")

    models = []
    for item in items:
        if isinstance(item, str):
            models.append({"name": item, "no_temperature": False})
        elif isinstance(item, dict):
            name = item.get("name") or item.get("model") or item.get("id")
            if not name:
                continue
            no_temp = bool(item.get("no_temperature")) or (item.get("supports_temperature") is False)
            models.append({"name": name, "no_temperature": no_temp})
        else:
            continue

    return models


def _error_indicates_temperature_unsupported(err_obj, raw_text):
    # Try to match typical OpenAI-style error shapes:
    # {"error": {"message": "...", "param": "temperature", ...}}
    try:
        e = err_obj.get("error", {}) if isinstance(err_obj, dict) else {}
        msg = str(e.get("message", "")).lower()
        param = str(e.get("param", "")).lower()
    except Exception:
        msg, param = "", ""

    blob = (raw_text or "").lower()
    if "temperature" in param:
        return True
    if "temperature" in msg and ("unsupported" in msg or "unknown" in msg or "not allowed" in msg):
        return True
    if "temperature" in blob and ("unsupported" in blob or "unknown" in blob or "not allowed" in blob):
        return True
    return False


def call_chat_completions(model_name, include_temperature=True):
    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
        "stream": False,
    }
    if include_temperature:
        payload["temperature"] = 0.0

    body = json.dumps(payload).encode("utf-8")

    headers = {"Content-Type": "application/json"}
    api_key = os.environ.get("OPENAI_API_KEY")
    if api_key:
        headers["Authorization"] = "Bearer " + api_key

    req = urllib.request.Request(API_URL, data=body, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        return json.loads(raw)


def test_model(model_name, allow_temperature=True):
    start = time.perf_counter()
    tried_with_temperature = allow_temperature

    try:
        try:
            data = call_chat_completions(model_name, include_temperature=tried_with_temperature)
        except urllib.error.HTTPError as e:
            raw = e.read().decode("utf-8", errors="replace")
            err_obj = None
            try:
                err_obj = json.loads(raw)
            except Exception:
                err_obj = None

            if tried_with_temperature and _error_indicates_temperature_unsupported(err_obj or {}, raw):
                # Retry without temperature
                tried_with_temperature = False
                data = call_chat_completions(model_name, include_temperature=False)
            else:
                raise RuntimeError(f"HTTP {e.code}: {raw.strip()[:200]}")

        content = (
            data.get("choices", [{}])[0]
            .get("message", {})
            .get("content", "")
        )
        latency = time.perf_counter() - start
        return latency, content, None

    except Exception as ex:
        latency = time.perf_counter() - start
        return latency, "", str(ex)


def format_table(rows):
    headers = ["Model", "Status", "Latency", "Response"]

    def clip(s, n):
        s = (s or "").replace("\n", " ").replace("\r", " ")
        return s if len(s) <= n else s[: n - 1] + "…"

    # Prepare clipped rows (Response first 50 chars)
    cooked = []
    for r in rows:
        cooked.append([
            r["model"],
            r["status"],
            f'{r["latency"]:.2f}s' if r["latency"] is not None else "",
            clip(r["response"], 50),
        ])

    cols = list(zip(*([headers] + cooked))) if cooked else [headers]
    widths = [min(max(len(str(x)) for x in col), 60) for col in cols]  # cap model col too

    def fmt_line(items):
        out = []
        for i, it in enumerate(items):
            s = str(it)
            if len(s) > widths[i]:
                s = s[: widths[i] - 1] + "…"
            out.append(s.ljust(widths[i]))
        return " | ".join(out)

    sep = "-+-".join("-" * w for w in widths)
    lines = [fmt_line(headers), sep]
    for r in cooked:
        lines.append(fmt_line(r))
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("config", help="Path to JSON config containing model list")
    args = ap.parse_args()

    try:
        models = load_models(args.config)
    except Exception as e:
        print(f"Failed to load config: {e}", file=sys.stderr)
        return 2

    results = []
    working = 0
    failed = 0

    for m in models:
        name = m["name"]
        allow_temperature = not m.get("no_temperature", False)

        latency, content, err = test_model(name, allow_temperature=allow_temperature)

        text = (content or "").strip()
        ok = (err is None) and (text == "OK")

        if ok:
            status = "PASS"
            working += 1
        else:
            status = "FAIL"
            failed += 1

        resp_preview = text if text else (err or "")
        results.append({
            "model": name,
            "status": status,
            "latency": latency,
            "response": resp_preview,
        })

    print(format_table(results))
    print(f"Total: {len(models)} models | ✅ {working} working | ❌ {failed} failed")
    return 0 if failed == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main())
